SELECT * FROM tb_ship
WHERE owner_id = #{ownerId}
ORDER BY rating DESC, created_at DESC

SELECT * FROM tb_ship
WHERE owner_id = #{ownerId}

    AND ship_type = #{shipType}

ORDER BY rating DESC, created_at DESC

SELECT * FROM tb_ship
WHERE status = 'AVAILABLE'

    AND ship_type = #{shipType}


    AND daily_rent >= #{minRent}


    AND daily_rent <= #{maxRent}


    AND tonnage >= #{minTonnage}


    AND tonnage <= #{maxTonnage}


    AND (ship_name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))



        ORDER BY daily_rent ASC, created_at DESC


        ORDER BY created_at DESC


        ORDER BY rating DESC, created_at DESC


        ORDER BY created_at DESC

SELECT COUNT(*) FROM tb_ship
WHERE owner_id = #{ownerId}

    AND status = #{status}
